// Minimal dynamic buffer replacing std::string / std::vector for raw
// binary/text data
struct DynamicBuffer {
    char* data = nullptr;
    size_t length = 0;
    size_t capacity = 0;

    void clear() {
        length = 0;
        if (data) {
            data[0] = '\0';
        }
    }

    void append(const char* src, size_t len) {
        if (!src || len == 0) return;
        if (length + len + 1 > capacity) {
            size_t newCap = (capacity == 0) ? 1024 : capacity * 2;
            while (newCap < length + len + 1) {
                newCap *= 2;
            }
            char* newBuf = static_cast<char*>(realloc(data, newCap));
            if (!newBuf) return;
            data = newBuf;
            capacity = newCap;
        }
        memcpy(data + length, src, len);
        length += len;
        data[length] = '\0';
    }

    void freeMem() {
        if (data) {
            free(data);
            data = nullptr;
        }
        length = 0;
        capacity = 0;
    }
};

static DynamicBuffer gClipboardDataStore;

static const char* kTextMimeTypes[] = {"text/plain;charset=utf-8", "text/plain",
                                       "UTF8_STRING", "STRING"};
constexpr size_t KMIME_TYPE_COUNT =
    sizeof(kTextMimeTypes) / sizeof(kTextMimeTypes[0]);

static void handleSourceTarget(void* data, wl_data_source* source,
                               const char* mime_type) {
    (void)data;
    (void)source;
    (void)mime_type;
}

static void handleSourceSend(void* data, wl_data_source* source,
                             const char* mime_type, int32_t fd) {
    (void)data;
    (void)source;

    bool typeMatches = false;
    for (size_t i = 0; i < KMIME_TYPE_COUNT; ++i) {
        if (mime_type && strcmp(mime_type, kTextMimeTypes[i]) == 0) {
            typeMatches = true;
            break;
        }
    }

    if (typeMatches && fd >= 0) {
        ssize_t written =
            write(fd, gClipboardDataStore.data ? gClipboardDataStore.data : "",
                  gClipboardDataStore.length);
        (void)written;
    }
    close(fd);
}

static void handleSourceCancelled(void* data, wl_data_source* source) {
    (void)data;
    wl_data_source_destroy(source);
}

static const wl_data_source_listener KDATA_SOURCE_LISTENER = {
    .target = handleSourceTarget,
    .send = handleSourceSend,
    .cancelled = handleSourceCancelled,
    .dnd_drop_performed = [](void*, wl_data_source*) {},
    .dnd_finished = [](void*, wl_data_source*) {},
    .action = [](void*, wl_data_source*, uint32_t) {},
};

void initializeClipboardWayland(WaylandContext& ctx) { (void)ctx; }

VeraStringView getClipboardTextWayland(WaylandContext& ctx) {
    if (!ctx.activeClipboardOffer) {
        return {};
    }

    const char* matchedMimeType = "text/plain;charset=utf-8";

    int fds[2];
    if (pipe2(fds, O_CLOEXEC | O_NONBLOCK) < 0) {
        return {};
    }

    wl_data_offer_receive(ctx.activeClipboardOffer, matchedMimeType, fds[1]);
    close(fds[1]);

    wl_display_flush(ctx.display);
    wl_display_roundtrip(ctx.display);

    gClipboardDataStore.clear();
    char buffer[1024];
    struct pollfd pfd = {.fd = fds[0], .events = POLLIN, .revents = 0};

    while (poll(&pfd, 1, 100) > 0) {
        ssize_t bytesRead = read(fds[0], buffer, sizeof(buffer));
        if (bytesRead <= 0) {
            break;
        }
        gClipboardDataStore.append(buffer, bytesRead);
    }

    close(fds[0]);
    return {.data = gClipboardDataStore.data,
            .length = gClipboardDataStore.length};
}

void setClipboardTextWayland(WaylandContext& ctx, const char* text,
                             size_t len) {
    if (!ctx.dataDeviceManager || !ctx.dataDevice) {
        printf("something was still undefined\n");
        return;
    }

    gClipboardDataStore.clear();
    if (text) {
        gClipboardDataStore.append(text, (len > 0) ? len : strlen(text));
    }

    wl_data_source* source =
        wl_data_device_manager_create_data_source(ctx.dataDeviceManager);
    if (!source) {
        return;
    }

    for (size_t i = 0; i < KMIME_TYPE_COUNT; ++i) {
        wl_data_source_offer(source, kTextMimeTypes[i]);
    }

    wl_data_source_add_listener(source, &KDATA_SOURCE_LISTENER, &ctx);

    wl_data_device_set_selection(ctx.dataDevice, source,
                                 ctx.lastPointerButtonSerial);

    wl_display_flush(ctx.display);
}

bool hasClipboardTextWayland(const WaylandContext& ctx) {
    return ctx.activeClipboardOffer != nullptr;
}

