static VeraDragCallback gDragCallback = nullptr;
static wl_data_offer* gActiveDndOffer = nullptr;
static double gLastDragX = 0.0;
static double gLastDragY = 0.0;

// In-place URL decoding without heap allocations
static size_t urlDecodeInPlace(char* str) {
    char* src = str;
    char* dst = str;
    while (*src) {
        if (*src == '%' && src[1] && src[2]) {
            int hexVal = 0;
            if (sscanf(src + 1, "%2x", &hexVal) == 1) {
                *dst++ = static_cast<char>(hexVal);
                src += 3;
                continue;
            }
        }
        if (*src == '+') {
            *dst++ = ' ';
            src++;
        } else {
            *dst++ = *src++;
        }
    }
    *dst = '\0';
    return static_cast<size_t>(dst - str);
}

// In-place line scanner populating a pre-allocated VeraStringView array
static size_t parseUriListInPlace(char* payload, VeraStringView* outViews,
                                  size_t maxViews) {
    size_t count = 0;
    char* line = payload;

    while (line && *line && count < maxViews) {
        char* nextLine = strchr(line, '\n');
        if (nextLine) {
            *nextLine = '\0';
        }

        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\r') {
            line[len - 1] = '\0';
            len--;
        }

        if (len > 0 && line[0] != '#') {
            if (strncmp(line, "file://", 7) == 0) {
                char* path = line + 7;
                size_t decodedLen = urlDecodeInPlace(path);
                outViews[count].data = path;
                outViews[count].length = decodedLen;
                count++;
            }
        }

        if (!nextLine) break;
        line = nextLine + 1;
    }

    return count;
}

static void handleDragEnter(void* data, wl_data_device* device, uint32_t serial,
                            wl_surface* surface, wl_fixed_t x, wl_fixed_t y,
                            wl_data_offer* offer) {
    (void)data;
    (void)device;
    (void)serial;
    (void)surface;

    gActiveDndOffer = offer;
    gLastDragX = wl_fixed_to_double(x);
    gLastDragY = wl_fixed_to_double(y);

    if (gActiveDndOffer) {
        wl_data_offer_accept(gActiveDndOffer, serial, "text/uri-list");
    }
}

static void handleDragMotion(void* data, wl_data_device* device, uint32_t time,
                             wl_fixed_t x, wl_fixed_t y) {
    (void)data;
    (void)device;
    (void)time;

    gLastDragX = wl_fixed_to_double(x);
    gLastDragY = wl_fixed_to_double(y);
}

static void handleDragLeave(void* data, wl_data_device* device) {
    (void)data;
    (void)device;
    gActiveDndOffer = nullptr;
}

static void handleDragDrop(void* data, wl_data_device* device) {
    auto* ctx = static_cast<WaylandContext*>(data);
    (void)device;

    if (!gActiveDndOffer || !gDragCallback) {
        return;
    }

    int fds[2];
    if (pipe2(fds, O_CLOEXEC | O_NONBLOCK) < 0) {
        return;
    }

    wl_data_offer_receive(gActiveDndOffer, "text/uri-list", fds[1]);
    close(fds[1]);

    wl_display_flush(ctx->display);
    wl_display_roundtrip(ctx->display);

    DynamicBuffer rawPayload;
    char buffer[1024];
    struct pollfd pfd = {.fd = fds[0], .events = POLLIN, .revents = 0};

    while (poll(&pfd, 1, 100) > 0) {
        ssize_t bytesRead = read(fds[0], buffer, sizeof(buffer));
        if (bytesRead <= 0) {
            break;
        }
        rawPayload.append(buffer, bytesRead);
    }
    close(fds[0]);

    if (rawPayload.length > 0) {
        constexpr size_t maxDragPaths = 128;
        VeraStringView viewArray[maxDragPaths];

        size_t pathCount =
            parseUriListInPlace(rawPayload.data, viewArray, maxDragPaths);

        if (pathCount > 0) {
            VeraDragEvent event{};
            event.paths = viewArray;
            event.pathCount = static_cast<uint32_t>(pathCount);
            event.x = gLastDragX;
            event.y = gLastDragY;

            gDragCallback(event);
        }
    }

    rawPayload.freeMem();

    wl_data_offer_finish(gActiveDndOffer);
    gActiveDndOffer = nullptr;
}

static const wl_data_device_listener KDATA_DEVICE_DND_LISTENER = {
    .data_offer = [](void*, wl_data_device*, wl_data_offer*) {},
    .enter = handleDragEnter,
    .leave = handleDragLeave,
    .motion = handleDragMotion,
    .drop = handleDragDrop,
    .selection = [](void*, wl_data_device*, wl_data_offer*) {}};

void initializeDnDWayland(WaylandContext& ctx) {
    if (ctx.dataDevice) {
        wl_data_device_add_listener(ctx.dataDevice, &KDATA_DEVICE_DND_LISTENER,
                                    &ctx);
    }
}

void setDragCallbackWayland(WaylandContext& ctx, VeraDragCallback callback) {
    (void)ctx;
    gDragCallback = callback;
}

void shutdownDnDWayland() {
    gDragCallback = nullptr;
    gActiveDndOffer = nullptr;
    gClipboardDataStore.freeMem();
}

