static nostd::Function<void(uint32_t, uint32_t, bool)> gButtonCallback;
static nostd::Function<void(uint32_t, uint32_t, float)> gAxisCallback;

void setJoystickButtonCallbackWayland(
    nostd::Function<void(uint32_t, uint32_t, bool)> cb) {
    gButtonCallback = cb;
}
void setJoystickAxisCallbackWayland(
    nostd::Function<void(uint32_t, uint32_t, float)> cb) {
    gAxisCallback = cb;
}

void initializeJoystickWayland(WaylandContext& ctx) {
    DIR* devDir = opendir("/dev/input");
    if (!devDir) return;

    struct dirent* entry;
    uint32_t slot = 0;

    while ((entry = readdir(devDir)) != nullptr &&
           slot < std::size(ctx.joysticks)) {
        // Fast prefix check for "js" without strncmp/<cstring>
        if (entry->d_name[0] == 'j' && entry->d_name[1] == 's') {
            // Construct "/dev/input/<d_name>" manually without snprintf
            char path[256] = "/dev/input/";
            size_t pos = 11;  // Length of "/dev/input/"

            for (size_t i = 0;
                 entry->d_name[i] != '\0' && pos < sizeof(path) - 1;
                 ++i, ++pos) {
                path[pos] = entry->d_name[i];
            }
            path[pos] = '\0';

            int fd = open(path, O_RDONLY | O_NONBLOCK);
            if (fd >= 0) {
                JoystickDeviceWayland& joy = ctx.joysticks[slot];
                joy.fd = fd;

                // Copy path string directly into member array
                size_t pIdx = 0;
                while (path[pIdx] != '\0' &&
                       pIdx < sizeof(joy.devicePath) - 1) {
                    joy.devicePath[pIdx] = path[pIdx];
                    pIdx++;
                }
                joy.devicePath[pIdx] = '\0';

                // Set fallback default name directly into target buffer
                const char defaultName[] = "Unknown Controller";
                size_t nIdx = 0;
                while (defaultName[nIdx] != '\0' &&
                       nIdx < sizeof(joy.state.name) - 1) {
                    joy.state.name[nIdx] = defaultName[nIdx];
                    nIdx++;
                }
                joy.state.name[nIdx] = '\0';

                // Pass joy.state.name directly to ioctl - avoids intermediate
                // copies entirely
                ioctl(fd, JSIOCGNAME(sizeof(joy.state.name)), joy.state.name);

                uint8_t axesCount = 0;
                uint8_t buttonsCount = 0;
                ioctl(fd, JSIOCGAXES, &axesCount);
                ioctl(fd, JSIOCGBUTTONS, &buttonsCount);

                joy.state.connected = true;
                joy.state.axes.resize(axesCount, 0.0f);
                joy.state.buttons.resize(buttonsCount, false);

                slot++;
            }
        }
    }
    closedir(devDir);
}

void updateJoystickWayland(WaylandContext& ctx) {
    (void)ctx;

    for (size_t i = 0; i < ctx.joysticks.size(); ++i) {
        JoystickDeviceWayland& joy = ctx.joysticks[i];
        if (joy.fd < 0) continue;

        struct js_event event;
        while (read(joy.fd, &event, sizeof(event)) > 0) {
            uint8_t type = event.type & ~JS_EVENT_INIT;

            if (type == JS_EVENT_BUTTON) {
                if (event.number < joy.state.buttons.size()) {
                    joy.state.buttons[event.number] = (event.value != 0);
                    if (gButtonCallback) {
                        gButtonCallback(static_cast<uint32_t>(i), event.number,
                                        joy.state.buttons[event.number]);
                    }
                }
            } else if (type == JS_EVENT_AXIS) {
                if (event.number < joy.state.axes.size()) {
                    joy.state.axes[event.number] =
                        static_cast<float>(event.value) / 32767.0f;
                    if (gAxisCallback) {
                        gAxisCallback(static_cast<uint32_t>(i), event.number,
                                      joy.state.axes[event.number]);
                    }
                }
            }
        }

        if (errno == ENODEV) {
            printf("[Joystick] Disconnected: %s\n", joy.state.name);
            close(joy.fd);
            joy.fd = -1;
            joy.state.connected = false;
        }
    }
}

VeraJoystickState getStateJoystickWayland(WaylandContext& ctx,
                                          uint32_t joystickId) {
    if (joystickId < ctx.joysticks.size()) {
        return ctx.joysticks[joystickId].state;
    }
    return VeraJoystickState{};
}

void shutdownJoystickWayland(WaylandContext& ctx) {
    (void)ctx;
    for (auto& joy : ctx.joysticks) {
        if (joy.fd >= 0) close(joy.fd);
        joy.fd = -1;
        joy.state.connected = false;
    }
}

