        // System & Editing Controls
        case KEY_ESC:
            return VeraKey::Escape;
        case KEY_ENTER:
            return VeraKey::Enter;
        case KEY_TAB:
            return VeraKey::Tab;
        case KEY_BACKSPACE:
            return VeraKey::Backspace;
        case KEY_INSERT:
            return VeraKey::Insert;
        case KEY_DELETE:
            return VeraKey::Delete;
        case KEY_HOME:
            return VeraKey::Home;
        case KEY_END:
            return VeraKey::End;
        case KEY_PAGEUP:
            return VeraKey::PageUp;
        case KEY_PAGEDOWN:
            return VeraKey::PageDown;

        // Navigation Arrows
        case KEY_LEFT:
            return VeraKey::Left;
        case KEY_RIGHT:
            return VeraKey::Right;
        case KEY_UP:
            return VeraKey::Up;
        case KEY_DOWN:
            return VeraKey::Down;

        // Modifiers
        case KEY_LEFTSHIFT:
            return VeraKey::LeftShift;
        case KEY_RIGHTSHIFT:
            return VeraKey::RightShift;
        case KEY_LEFTCTRL:
