        case KEY_LEFTALT:
            return VeraKey::LeftAlt;
        case KEY_RIGHTALT:
            return VeraKey::RightAlt;
        case KEY_LEFTMETA:
            return VeraKey::LeftSuper;
        case KEY_RIGHTMETA:
            return VeraKey::RightSuper;

        // Locks & Utility
        case KEY_CAPSLOCK:
            return VeraKey::CapsLock;
        case KEY_SCROLLLOCK:
            return VeraKey::ScrollLock;
        case KEY_NUMLOCK:
            return VeraKey::NumLock;
        case KEY_PRINT:
            return VeraKey::PrintScreen;
        case KEY_PAUSE:
            return VeraKey::Pause;
        case KEY_COMPOSE:
            return VeraKey::Menu;

        // Function Keys
        case KEY_F1:
            return VeraKey::F1;
        case KEY_F2:
            return VeraKey::F2;
        case KEY_F3:
            return VeraKey::F3;
        case KEY_F4:
            return VeraKey::F4;
        case KEY_F5:
            return VeraKey::F5;
        case KEY_F6:
            return VeraKey::F6;
        case KEY_F7:
            return VeraKey::F7;
        case KEY_F8:
            return VeraKey::F8;
        case KEY_F9:
            return VeraKey::F9;
        case KEY_F10:
            return VeraKey::F10;
        case KEY_F11:
            return VeraKey::F11;
        case KEY_F12:
            return VeraKey::F12;

        // Keypad
        case KEY_KP0:
            return VeraKey::KP0;
        case KEY_KP1:
            return VeraKey::KP1;
        case KEY_KP2:
            return VeraKey::KP2;
        case KEY_KP3:
            return VeraKey::KP3;
        case KEY_KP4:
            return VeraKey::KP4;
        case KEY_KP5:
            return VeraKey::KP5;
        case KEY_KP6:
            return VeraKey::KP6;
        case KEY_KP7:
            return VeraKey::KP7;
        case KEY_KP8:
            return VeraKey::KP8;
        case KEY_KP9:
            return VeraKey::KP9;
        case KEY_KPDOT:
            return VeraKey::KPDecimal;
        case KEY_KPSLASH:
            return VeraKey::KPDivide;
        case KEY_KPASTERISK:
