static double sPointerX = 0.0;
static double sPointerY = 0.0;
static WaylandWindow* sPointerTargetWindow = nullptr;

static VeraMouseButton translateMouseButton(uint32_t button) {
    switch (button) {
        case BTN_LEFT:
            return VeraMouseButton::Left;
        case BTN_RIGHT:
            return VeraMouseButton::Right;
        case BTN_MIDDLE:
            return VeraMouseButton::Middle;
        case BTN_SIDE:
            return VeraMouseButton::VeraButton4;
        case BTN_EXTRA:
            return VeraMouseButton::VeraButton5;
        default:
            return VeraMouseButton::Count;
    }
}

static void pointerHandleEnter(void* data, wl_pointer* pointer, uint32_t serial,
                               wl_surface* surface, wl_fixed_t sx,
                               wl_fixed_t sy) {
    auto* ctx = static_cast<WaylandContext*>(data);

    // 1. Un-suppress and map input arguments to the operational context
    ctx->pointer = pointer;
    ctx->pointerSerial = serial;

    WaylandWindow* window = ctx->findWindowBySurface(surface);
    if (window) {
        sPointerTargetWindow = window;
        sPointerX = wl_fixed_to_double(sx);
        sPointerY = wl_fixed_to_double(sy);
    }

    // 2. Commit your stored cursor configuration with the active validation
    // token
    applyCursorToWayland(*ctx, serial);
}

static void pointerHandleLeave(void* data, wl_pointer* pointer, uint32_t serial,
                               wl_surface* surface) {
    auto* ctx = static_cast<WaylandContext*>(data);
    (void)pointer;
    (void)serial;
    (void)surface;

    // Invalidate state mapping flags
    sPointerTargetWindow = nullptr;
    if (ctx) {
        ctx->pointerSerial = 0;
    }
}

static void pointerHandleMotion(void* data, wl_pointer* pointer, uint32_t time,
                                wl_fixed_t sx, wl_fixed_t sy) {
    (void)data;
    (void)pointer;
    (void)time;
    sPointerX = wl_fixed_to_double(sx);
    sPointerY = wl_fixed_to_double(sy);
}

static void pointerHandleButton(void* data, wl_pointer* pointer,
                                uint32_t serial, uint32_t time, uint32_t button,
                                uint32_t state) {
    auto* ctx = static_cast<WaylandContext*>(data);
    (void)pointer;
    (void)time;

    // Capture the valid user input serial for actions like clipboard selection
    if (ctx) {
        ctx->lastPointerButtonSerial = serial;
    }

    if (!sPointerTargetWindow) return;

    // Optional but recommended: Update pointer token on structural button
    // presses
    if (ctx) {
        ctx->pointerSerial = serial;
    }

    VeraMouseButton veraButton = translateMouseButton(button);
    bool pressed = (state == WL_POINTER_BUTTON_STATE_PRESSED);

    if (sPointerTargetWindow->getMouseButtonCallback()) {
        sPointerTargetWindow->getMouseButtonCallback()(veraButton, pressed);
    }
}

static void pointerHandleAxis(void* data, wl_pointer* pointer, uint32_t time,
                              uint32_t axis, wl_fixed_t value) {
    (void)data;
    (void)pointer;
    (void)time;

    if (!sPointerTargetWindow) return;

    double scrollVal = wl_fixed_to_double(value);
    double normScroll = -scrollVal / 10.0;

    if (sPointerTargetWindow->getScrollCallback()) {
        if (axis == WL_POINTER_AXIS_VERTICAL_SCROLL) {
            sPointerTargetWindow->getScrollCallback()(0.0, normScroll);
        } else if (axis == WL_POINTER_AXIS_HORIZONTAL_SCROLL) {
            sPointerTargetWindow->getScrollCallback()(normScroll, 0.0);
        }
    }
}

static void pointerHandleFrame(void* data, wl_pointer* pointer) {
    (void)data;
    (void)pointer;

    if (sPointerTargetWindow && sPointerTargetWindow->getMouseMoveCallback()) {
        sPointerTargetWindow->getMouseMoveCallback()(sPointerX, sPointerY);
    }
}

static void pointerHandleAxisSource(void* data, wl_pointer* pointer,
                                    uint32_t axis_source) {
    (void)data;
    (void)pointer;
    (void)axis_source;
}

static void pointerHandleAxisStop(void* data, wl_pointer* pointer,
                                  uint32_t time, uint32_t axis) {
    (void)data;
    (void)pointer;
    (void)time;
    (void)axis;
}

static void pointerHandleAxisDiscrete(void* data, wl_pointer* pointer,
                                      uint32_t axis, int32_t discrete) {
    (void)data;
    (void)pointer;
    (void)axis;
    (void)discrete;
}

static const wl_pointer_listener KPOINTER_LISTENER = {
    .enter = pointerHandleEnter,
    .leave = pointerHandleLeave,
    .motion = pointerHandleMotion,
    .button = pointerHandleButton,
    .axis = pointerHandleAxis,
    .frame = pointerHandleFrame,
    .axis_source = pointerHandleAxisSource,
    .axis_stop = pointerHandleAxisStop,
    .axis_discrete = pointerHandleAxisDiscrete,
    .axis_value120 = nullptr,
    .axis_relative_direction = nullptr,
    .warp = nullptr,
};

void addListenerToPointer(WaylandContext& ctx, wl_pointer* pointer) {
    if (pointer) {
        wl_pointer_add_listener(pointer, &KPOINTER_LISTENER, &ctx);
    }
}

nostd::Vector<VeraMonitorInfo> getMonitorsWayland(const WaylandContext& ctx) {
    nostd::Vector<VeraMonitorInfo> list;
    list.reserve(ctx.outputCount);

    for (const auto& out : ctx.outputs) {
        VeraMonitorInfo info{};
        info.name = !out.name ? "Generic Wayland Display" : out.name;

        info.x = out.x;
        info.y = out.y;

        info.workAreaX = out.x;
        info.workAreaY = out.y;
        info.workAreaWidth = (out.widthMm > 0) ? out.widthMm : 1920;
        info.workAreaHeight = (out.heightMm > 0) ? out.heightMm : 1080;

        info.dpiScale = static_cast<float>(out.scaleFactor);

        info.refreshRateHz = static_cast<uint32_t>(out.refreshRate / 1000);
        info.isPrimary = out.isPrimary;

        if (out.widthMm > 0 && out.heightMm > 0) {
            info.physicalWidthMm = static_cast<uint32_t>(out.widthMm);
            info.physicalHeightMm = static_cast<uint32_t>(out.heightMm);
        }

        list.push_back(info);
    }

    return list;
}

VeraMonitorInfo getPrimaryMonitorWayland(const WaylandContext& ctx) {
    for (const auto& out : ctx.outputs) {
        if (out.isPrimary) {
            auto monitors = getMonitorsWayland(ctx);
            for (const auto& m : monitors) {
                if (m.name == out.name) return m;
            }
        }
    }

    auto monitors = getMonitorsWayland(ctx);
    if (!monitors.empty()) {
        return monitors.front();
    }

    return VeraMonitorInfo{};
}

VeraMonitorInfo getMonitorAtCoordinateXYWayland(const WaylandContext& ctx,
                                                int32_t x, int32_t y) {
    auto monitors = getMonitorsWayland(ctx);
    if (monitors.empty()) return VeraMonitorInfo{};

    for (const auto& monitor : monitors) {
        if (x >= monitor.x &&
            x < (monitor.x + static_cast<int32_t>(monitor.workAreaWidth)) &&
            y >= monitor.y &&
            y < (monitor.y + static_cast<int32_t>(monitor.workAreaHeight))) {
            return monitor;
        }
    }

    return monitors.front();
}

nostd::Vector<VeraDisplayModeInfo> getSupportedDisplayModesWayland(
    const WaylandContext& ctx, const VeraMonitorInfo& monitor) {
    nostd::Vector<VeraDisplayModeInfo> modes;

    for (const auto& out : ctx.outputs) {
        if (out.name == monitor.name) {
            VeraDisplayModeInfo mode{};
            mode.width = monitor.workAreaWidth;
            mode.height = monitor.workAreaHeight;
            mode.refreshRateHz = static_cast<uint32_t>(out.refreshRate / 1000);
            mode.bitsPerPixel = 32;
            modes.push_back(mode);
            break;
        }
    }

    return modes;
}

